insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('96341d2c-8bfe-4ead-beee-baaae8585be7', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Proof toolkit', 'This module establishes proof toolkit as the course''s first working framework. It supplies the language and representations needed before the path advances to real numbers and completeness.', 0),
  ('ea9e2522-fb70-4cd9-9f50-286efd9a77bb', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '96341d2c-8bfe-4ead-beee-baaae8585be7', 'subtopic'::public.curated_course_node_type, 'Logic', 'Logic provides a formal guarantee or inference rule for proof toolkit, allowing later conclusions to be justified rather than inferred from examples alone. It appears before quantifiers because that next topic assumes this starting point.', 0),
  ('21aa13eb-2959-482b-b611-959511fffb36', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '96341d2c-8bfe-4ead-beee-baaae8585be7', 'subtopic'::public.curated_course_node_type, 'Quantifiers', 'Quantifiers provides a formal guarantee or inference rule for proof toolkit, allowing later conclusions to be justified rather than inferred from examples alone. After logic, quantifiers supplies what is needed to address sets.', 1),
  ('642117d7-53fe-4b22-8089-62862f59a177', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '96341d2c-8bfe-4ead-beee-baaae8585be7', 'subtopic'::public.curated_course_node_type, 'Sets', 'Sets identifies a specific object, distinction, or relationship within proof toolkit. Learners need to recognize and use it before combining this module''s ideas in later work. After quantifiers, sets supplies what is needed to address functions.', 2),
  ('a95a7714-dd45-402f-b077-5c725fba4767', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '96341d2c-8bfe-4ead-beee-baaae8585be7', 'subtopic'::public.curated_course_node_type, 'Functions', 'Functions identifies a specific object, distinction, or relationship within proof toolkit. Learners need to recognize and use it before combining this module''s ideas in later work. After sets, functions supplies what is needed to address induction.', 3),
  ('c346d2c0-8175-4dd9-ab8b-97406ea8d967', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '96341d2c-8bfe-4ead-beee-baaae8585be7', 'subtopic'::public.curated_course_node_type, 'Induction', 'Induction provides a formal guarantee or inference rule for proof toolkit, allowing later conclusions to be justified rather than inferred from examples alone. After functions, induction supplies what is needed to address contradiction.', 4),
  ('83d15da8-91d4-4dec-8442-9a17874635a9', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '96341d2c-8bfe-4ead-beee-baaae8585be7', 'subtopic'::public.curated_course_node_type, 'Contradiction', 'Contradiction provides a formal guarantee or inference rule for proof toolkit, allowing later conclusions to be justified rather than inferred from examples alone. As the final topic in this module, contradiction carries the completed idea into real numbers and completeness.', 5),
  ('b81bf166-fe0b-4cca-bb72-4e33915c8f25', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Real numbers and completeness', 'This module builds directly on proof toolkit and develops real numbers and completeness. It belongs here because its methods and distinctions are prerequisites for sequences.', 1),
  ('bd26eef9-5a84-4440-9e5c-4cdfef861d8f', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'b81bf166-fe0b-4cca-bb72-4e33915c8f25', 'subtopic'::public.curated_course_node_type, 'Bounds', 'Bounds identifies a specific object, distinction, or relationship within real numbers and completeness. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before supremum because that next topic assumes this starting point.', 0),
  ('e8f6bce8-c5ed-4a24-84f7-d912194cfbd7', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'b81bf166-fe0b-4cca-bb72-4e33915c8f25', 'subtopic'::public.curated_course_node_type, 'Supremum', 'Supremum identifies a specific object, distinction, or relationship within real numbers and completeness. Learners need to recognize and use it before combining this module''s ideas in later work. After bounds, supremum supplies what is needed to address archimedean property.', 1),
  ('2482ddc4-49d5-49a4-82e6-8dea65a4379f', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'b81bf166-fe0b-4cca-bb72-4e33915c8f25', 'subtopic'::public.curated_course_node_type, 'Archimedean property', 'Archimedean property identifies a specific object, distinction, or relationship within real numbers and completeness. Learners need to recognize and use it before combining this module''s ideas in later work. After supremum, archimedean property supplies what is needed to address density.', 2),
  ('9ae81261-31b4-4f14-8901-d0a78f3263b4', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'b81bf166-fe0b-4cca-bb72-4e33915c8f25', 'subtopic'::public.curated_course_node_type, 'Density', 'Density identifies a specific object, distinction, or relationship within real numbers and completeness. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, density carries the completed idea into sequences.', 3),
  ('4756ea56-397a-4f8b-b1d6-037e4f92c955', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Sequences', 'This module builds directly on real numbers and completeness and develops sequences. It belongs here because its methods and distinctions are prerequisites for series.', 2),
  ('0f890660-e609-474d-b301-44cbaf449abf', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '4756ea56-397a-4f8b-b1d6-037e4f92c955', 'subtopic'::public.curated_course_node_type, 'Convergence', 'Convergence makes difficult behavior in sequences tractable while exposing the assumptions and accuracy limits used by later methods. It appears before subsequences because that next topic assumes this starting point.', 0),
  ('26836c39-801b-40aa-9380-2e70ce151913', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '4756ea56-397a-4f8b-b1d6-037e4f92c955', 'subtopic'::public.curated_course_node_type, 'Subsequences', 'Subsequences identifies a specific object, distinction, or relationship within sequences. Learners need to recognize and use it before combining this module''s ideas in later work. After convergence, subsequences supplies what is needed to address cauchy criterion.', 1),
  ('1b3d8679-6774-4beb-a7f8-5e7b434515ee', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '4756ea56-397a-4f8b-b1d6-037e4f92c955', 'subtopic'::public.curated_course_node_type, 'Cauchy criterion', 'Cauchy criterion identifies a specific object, distinction, or relationship within sequences. Learners need to recognize and use it before combining this module''s ideas in later work. After subsequences, cauchy criterion supplies what is needed to address limsup/liminf.', 2),
  ('d762cf3c-3502-45ff-8c49-b898330d20bc', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '4756ea56-397a-4f8b-b1d6-037e4f92c955', 'subtopic'::public.curated_course_node_type, 'Limsup/liminf', 'Limsup/liminf identifies a specific object, distinction, or relationship within sequences. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, limsup/liminf carries the completed idea into series.', 3),
  ('83a0cb9b-f148-46b7-8442-0f8d82b85392', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Series', 'This module builds directly on sequences and develops series. It belongs here because its methods and distinctions are prerequisites for metric-space foundations.', 3),
  ('b0556012-e5a7-447c-a286-22992ed6e446', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '83a0cb9b-f148-46b7-8442-0f8d82b85392', 'subtopic'::public.curated_course_node_type, 'Absolute/conditional convergence', 'Absolute/conditional convergence makes difficult behavior in series tractable while exposing the assumptions and accuracy limits used by later methods. It appears before comparison because that next topic assumes this starting point.', 0),
  ('e730fa25-fb8b-438e-a4e9-e776906a6cf1', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '83a0cb9b-f148-46b7-8442-0f8d82b85392', 'subtopic'::public.curated_course_node_type, 'Comparison', 'Comparison identifies a specific object, distinction, or relationship within series. Learners need to recognize and use it before combining this module''s ideas in later work. After absolute/conditional convergence, comparison supplies what is needed to address ratio/root tests.', 1),
  ('50f64037-48f0-44de-a1e0-06d964eb2fab', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '83a0cb9b-f148-46b7-8442-0f8d82b85392', 'subtopic'::public.curated_course_node_type, 'Ratio/root tests', 'Ratio/root tests identifies a specific object, distinction, or relationship within series. Learners need to recognize and use it before combining this module''s ideas in later work. After comparison, ratio/root tests supplies what is needed to address rearrangement.', 2),
  ('bfe37bba-f274-4ee6-ae3a-2c1b53f5b707', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '83a0cb9b-f148-46b7-8442-0f8d82b85392', 'subtopic'::public.curated_course_node_type, 'Rearrangement', 'Rearrangement identifies a specific object, distinction, or relationship within series. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, rearrangement carries the completed idea into metric-space foundations.', 3),
  ('2207b1e8-0d2d-4341-bc21-82175f2bf674', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Metric-space foundations', 'This module builds directly on series and develops metric-space foundations. It belongs here because its methods and distinctions are prerequisites for compactness.', 4),
  ('e19ed95c-eb50-49d4-86da-4341ec27cde3', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '2207b1e8-0d2d-4341-bc21-82175f2bf674', 'subtopic'::public.curated_course_node_type, 'Open/closed sets', 'Open/closed sets identifies a specific object, distinction, or relationship within metric-space foundations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before neighborhoods because that next topic assumes this starting point.', 0),
  ('a890ffea-6433-4660-a483-13a1cec430e6', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '2207b1e8-0d2d-4341-bc21-82175f2bf674', 'subtopic'::public.curated_course_node_type, 'Neighborhoods', 'Neighborhoods identifies a specific object, distinction, or relationship within metric-space foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After open/closed sets, neighborhoods supplies what is needed to address continuity.', 1),
  ('3ea4c4a4-361a-4626-a430-28d85718b85e', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '2207b1e8-0d2d-4341-bc21-82175f2bf674', 'subtopic'::public.curated_course_node_type, 'Continuity', 'Continuity identifies a specific object, distinction, or relationship within metric-space foundations. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, continuity carries the completed idea into compactness.', 2),
  ('5ba0a9ec-c57c-4e7f-a279-e291943e882a', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Compactness', 'This module builds directly on metric-space foundations and develops compactness. It belongs here because its methods and distinctions are prerequisites for connectedness and uniform continuity.', 5),
  ('010c2b7f-a5c3-4f15-9bf7-38028038c57d', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '5ba0a9ec-c57c-4e7f-a279-e291943e882a', 'subtopic'::public.curated_course_node_type, 'Heine–Borel', 'Heine–Borel identifies a specific object, distinction, or relationship within compactness. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before sequential compactness because that next topic assumes this starting point.', 0),
  ('b1ea2014-146c-4102-ba4f-66705ab41d5d', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '5ba0a9ec-c57c-4e7f-a279-e291943e882a', 'subtopic'::public.curated_course_node_type, 'Sequential compactness', 'Sequential compactness provides a formal guarantee or inference rule for compactness, allowing later conclusions to be justified rather than inferred from examples alone. After heine–borel, sequential compactness supplies what is needed to address finite subcovers.', 1),
  ('6a620033-b4a1-48d8-92a5-8defc6915fcc', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '5ba0a9ec-c57c-4e7f-a279-e291943e882a', 'subtopic'::public.curated_course_node_type, 'Finite subcovers', 'Finite subcovers identifies a specific object, distinction, or relationship within compactness. Learners need to recognize and use it before combining this module''s ideas in later work. After sequential compactness, finite subcovers supplies what is needed to address applications.', 2),
  ('dda4e7e2-6cd0-4c26-ae6e-fc3938125fec', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '5ba0a9ec-c57c-4e7f-a279-e291943e882a', 'subtopic'::public.curated_course_node_type, 'Applications', 'Applications identifies a specific object, distinction, or relationship within compactness. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, applications carries the completed idea into connectedness and uniform continuity.', 3),
  ('27eb50eb-03f9-4e59-b8ba-d24df76b7c2f', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Connectedness and uniform continuity', 'This module builds directly on compactness and develops connectedness and uniform continuity. It belongs here because its methods and distinctions are prerequisites for differentiation.', 6),
  ('ef587c9b-8ed6-45f8-82e6-ed3def2ce930', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '27eb50eb-03f9-4e59-b8ba-d24df76b7c2f', 'subtopic'::public.curated_course_node_type, 'Intermediate values', 'Intermediate values identifies a specific object, distinction, or relationship within connectedness and uniform continuity. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before compact-domain consequences because that next topic assumes this starting point.', 0),
  ('58903739-2d59-47cc-91b5-b5e3202bb593', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '27eb50eb-03f9-4e59-b8ba-d24df76b7c2f', 'subtopic'::public.curated_course_node_type, 'Compact-domain consequences', 'Compact-domain consequences identifies a specific object, distinction, or relationship within connectedness and uniform continuity. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, compact-domain consequences carries the completed idea into differentiation.', 1),
  ('7b780a24-afe5-48d8-8a54-fd50887598af', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Differentiation', 'This module builds directly on connectedness and uniform continuity and develops differentiation. It belongs here because its methods and distinctions are prerequisites for riemann integration.', 7),
  ('1ae42e82-3c71-414f-8d25-10afede8a56c', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '7b780a24-afe5-48d8-8a54-fd50887598af', 'subtopic'::public.curated_course_node_type, 'Mean value theorem', 'Mean value theorem provides a formal guarantee or inference rule for differentiation, allowing later conclusions to be justified rather than inferred from examples alone. It appears before taylor theorem because that next topic assumes this starting point.', 0),
  ('7cf2016d-d812-4378-833b-950172aecc90', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '7b780a24-afe5-48d8-8a54-fd50887598af', 'subtopic'::public.curated_course_node_type, 'Taylor theorem', 'Taylor theorem provides a formal guarantee or inference rule for differentiation, allowing later conclusions to be justified rather than inferred from examples alone. After mean value theorem, taylor theorem supplies what is needed to address inverse/implicit viewpoints.', 1),
  ('916b1203-8cae-47e9-b7b5-f28cd6bb4e83', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '7b780a24-afe5-48d8-8a54-fd50887598af', 'subtopic'::public.curated_course_node_type, 'Inverse/implicit viewpoints', 'Inverse/implicit viewpoints identifies a specific object, distinction, or relationship within differentiation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, inverse/implicit viewpoints carries the completed idea into riemann integration.', 2),
  ('7fd7a09d-4468-4556-bc50-dcf84520b6c2', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Riemann integration', 'This module builds directly on differentiation and develops riemann integration. It belongs here because its methods and distinctions are prerequisites for sequences of functions.', 8),
  ('8099c31c-1d2a-4282-9f8d-618dbec36a92', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '7fd7a09d-4468-4556-bc50-dcf84520b6c2', 'subtopic'::public.curated_course_node_type, 'Upper/lower sums', 'Upper/lower sums identifies a specific object, distinction, or relationship within riemann integration. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before integrability criteria because that next topic assumes this starting point.', 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e91f1a28-9fb4-4053-be65-4a1b1c28d911', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '7fd7a09d-4468-4556-bc50-dcf84520b6c2', 'subtopic'::public.curated_course_node_type, 'Integrability criteria', 'Integrability criteria identifies a specific object, distinction, or relationship within riemann integration. Learners need to recognize and use it before combining this module''s ideas in later work. After upper/lower sums, integrability criteria supplies what is needed to address ftc.', 1),
  ('5c4a0b86-aabb-4ebc-a45a-e09b99eee033', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '7fd7a09d-4468-4556-bc50-dcf84520b6c2', 'subtopic'::public.curated_course_node_type, 'FTC', 'FTC identifies a specific object, distinction, or relationship within riemann integration. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, ftc carries the completed idea into sequences of functions.', 2),
  ('32cfefa7-2dd7-48ff-8b1d-649b5348b5b9', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Sequences of functions', 'This module builds directly on riemann integration and develops sequences of functions. It belongs here because its methods and distinctions are prerequisites for power series and approximation.', 9),
  ('441023ac-56b5-4492-8980-5083b3a2ffb0', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '32cfefa7-2dd7-48ff-8b1d-649b5348b5b9', 'subtopic'::public.curated_course_node_type, 'Pointwise vs uniform convergence', 'Pointwise vs uniform convergence makes difficult behavior in sequences of functions tractable while exposing the assumptions and accuracy limits used by later methods. It appears before interchange of limits because that next topic assumes this starting point.', 0),
  ('7ff8d232-0d9f-4ee9-834c-46b60dd74d5a', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '32cfefa7-2dd7-48ff-8b1d-649b5348b5b9', 'subtopic'::public.curated_course_node_type, 'Interchange of limits', 'Interchange of limits makes difficult behavior in sequences of functions tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, interchange of limits carries the completed idea into power series and approximation.', 1),
  ('52f1e63f-c896-4c26-beaa-c599f7a5707a', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Power series and approximation', 'This module builds directly on sequences of functions and develops power series and approximation. It belongs here because its methods and distinctions are prerequisites for multivariable extension.', 10),
  ('fe99dedb-75ac-4432-939c-b3b3d6cc0d35', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '52f1e63f-c896-4c26-beaa-c599f7a5707a', 'subtopic'::public.curated_course_node_type, 'Uniform convergence', 'Uniform convergence makes difficult behavior in power series and approximation tractable while exposing the assumptions and accuracy limits used by later methods. It appears before weierstrass ideas because that next topic assumes this starting point.', 0),
  ('c0fe8757-9203-4ee3-b629-3cf88cd6f72d', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '52f1e63f-c896-4c26-beaa-c599f7a5707a', 'subtopic'::public.curated_course_node_type, 'Weierstrass ideas', 'Weierstrass ideas identifies a specific object, distinction, or relationship within power series and approximation. Learners need to recognize and use it before combining this module''s ideas in later work. After uniform convergence, weierstrass ideas supplies what is needed to address function spaces.', 1),
  ('c4da9bb9-8724-402d-8955-a2eb8db4c512', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', '52f1e63f-c896-4c26-beaa-c599f7a5707a', 'subtopic'::public.curated_course_node_type, 'Function spaces', 'Function spaces gives power series and approximation a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, function spaces carries the completed idea into multivariable extension.', 2),
  ('d7086453-9978-4771-933b-2b5dd748b8cd', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', null, 'topic'::public.curated_course_node_type, 'Multivariable extension', 'This culminating module draws on power series and approximation and develops multivariable extension. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('de40e4a4-b1a6-4b5c-ae50-97a06fa5cb86', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'd7086453-9978-4771-933b-2b5dd748b8cd', 'subtopic'::public.curated_course_node_type, 'Norms', 'Norms identifies a specific object, distinction, or relationship within multivariable extension. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before derivatives as linear maps because that next topic assumes this starting point.', 0),
  ('9e5bc41c-3e81-4619-bc5b-7a485896a03a', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'd7086453-9978-4771-933b-2b5dd748b8cd', 'subtopic'::public.curated_course_node_type, 'Derivatives as linear maps', 'Derivatives as linear maps gives multivariable extension a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After norms, derivatives as linear maps supplies what is needed to address contraction/fixed-point glimpse.', 1),
  ('262a3ce5-fae8-48c0-9824-58557a11caeb', 'a5b6c7d8-9e0f-4a03-8b24-3c4d5e6f7a33', 'd7086453-9978-4771-933b-2b5dd748b8cd', 'subtopic'::public.curated_course_node_type, 'Contraction/fixed-point glimpse', 'Contraction/fixed-point glimpse identifies a specific object, distinction, or relationship within multivariable extension. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, contraction/fixed-point glimpse requires ideas from the complete path to be integrated and transferred.', 2);
